render='''impl Render for Ribbon {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let theme = cx.theme();
        let (border, muted) = (theme.border, theme.muted_foreground);
        let project = ProjectDirectory::get(cx);

        // Each tab handles its own clicks, so a double-click can be told
        // apart: it collapses or expands the ribbon.
        let tabs = RibbonTab::ALL.map(|tab| {
            Tab::new()
                .label(tab.label())
                .on_click(cx.listener(move |this, event: &ClickEvent, _, cx| {
                    this.tab_clicked(tab, event.click_count(), cx)
                }))
        });
        let collapse = Button::new("ribbon-collapse")
            .ghost()
            .xsmall()
            .icon(if self.collapsed {
                IconName::ChevronDown
            } else {
                IconName::ChevronUp
            })
            .tooltip_with_action(
                if self.collapsed {
                    "Expand the ribbon"
                } else {
                    "Collapse the ribbon to its tabs"
                },
                &ToggleRibbon,
                None,
            )
            .on_click(cx.listener(|this, _, _, cx| this.toggle_collapsed(cx)));
        let tab_bar = TabBar::new("ribbon-tabs")
            .selected_index(self.selected_tab.index())
            .children(tabs)
            .suffix(div().px_2().child(collapse));

        let groups: Vec<AnyElement> = match self.selected_tab {
            RibbonTab::Project => {
                let (label, tooltip): (SharedString, SharedString) = match &project {
                    Some(dir) => (
                        dir.file_name()
                            .map(|name| name.to_string_lossy().into_owned())
                            .unwrap_or_default()
                            .into(),
                        format!("{}\\nOpen a different piton.config.pi", dir.display()).into(),
                    ),
                    None => (
                        "Open Project…".into(),
                        "Pick a piton.config.pi file; its folder becomes the project".into(),
                    ),
                };
                vec![group(
                    "Project",
                    vec![
                        command("project-directory", IconName::FolderOpen, label)
                            .tooltip(tooltip)
                            .on_click(
                                cx.listener(|this, _, window, cx| this.pick_project(window, cx)),
                            )
                            .into_any_element(),
                    ],
                    muted,
                )]
            }
            RibbonTab::Code | RibbonTab::Research => vec![
                div()
                    .text_sm()
                    .text_color(muted)
                    .child("No commands yet")
                    .into_any_element(),
            ],
            RibbonTab::Spec => {
                // Disabled rather than hidden, so it is always found in the
                // same place, with the tooltip saying why.
                let tooltip = if project.is_none() {
                    "Open a project to build its spec"
                } else if self.building {
                    "The spec is building"
                } else {
                    "Run piton build to compile the spec"
                };
                vec![group(
                    "Build",
                    vec![
                        command("build", IconName::Hammer, "Build Spec")
                            .tooltip(tooltip)
                            .loading(self.building)
                            .disabled(project.is_none() || self.building)
                            .on_click(cx.listener(|this, _, window, cx| this.build(window, cx)))
                            .into_any_element(),
                    ],
                    muted,
                )]
            }
            RibbonTab::Application => vec![
                group(
                    "Appearance",
                    vec![
                        gpui_kit::component::switch::Switch::new("dark-mode")
                            .label("Dark mode")
                            .checked(cx.theme().is_dark())
                            .on_click(|dark, window, cx| set_dark_mode(*dark, window, cx))
                            .into_any_element(),
                    ],
                    muted,
                ),
                group(
                    "Preferences",
                    vec![
                        command("settings", IconName::Settings, "Settings")
                            .tooltip_with_action(
                                "Edit the system prompt each chat tab sends",
                                &OpenSettings,
                                None,
                            )
                            .on_click(|_, _, cx| crate::settings_window::open(cx))
                            .into_any_element(),
                    ],
                    muted,
                ),
            ],
        };
        // Groups side by side, a divider between each.
        let mut row = Vec::new();
        for (ix, group) in groups.into_iter().enumerate() {
            if ix > 0 {
                row.push(div().w_px().my_2().bg(border).into_any_element());
            }
            row.push(group);
        }

        div()
            .id("ribbon")
            .flex()
            .flex_col()
            .border_b_1()
            .border_color(border)
            .child(tab_bar)
            .when(!self.collapsed, |ribbon| {
                ribbon.child(
                    div()
                        .id("ribbon-controls")
                        .flex()
                        .flex_row()
                        .items_stretch()
                        .gap_2()
                        .px_2()
                        // Every tab is as tall, so the window beneath doesn't
                        // jump when switching tabs.
                        .h(RIBBON_BODY_HEIGHT)
                        .children(row),
                )
            })
    }
}

/// A group of related commands, labelled along its bottom.
fn group(label: &'static str, commands: Vec<AnyElement>, muted: Hsla) -> AnyElement {
    v_flex()
        .id(label)
        .h_full()
        .px_1()
        .child(
            h_flex()
                .flex_1()
                .items_center()
                .gap_2()
                .children(commands),
        )
        .child(
            div()
                .pb_1()
                .text_xs()
                .text_center()
                .text_color(muted)
                .child(label),
        )
        .into_any_element()
}

/// A command button: a large icon above its label.
fn command(id: &'static str, icon: IconName, label: impl Into<SharedString>) -> Button {
    Button::new(id).ghost().h(px(52.)).px_3().child(
        v_flex()
            .items_center()
            .gap_1()
            .child(Icon::new(icon).with_size(Size::Large))
            .child(div().text_xs().child(label.into())),
    )
}

