                            .tooltip(tooltip)
                            .loading(self.building)
                            .disabled(project.is_none() || self.building)
                            .on_click(cx.listener(|this, _, window, cx| this.build(window, cx)))
                            .into_any_element(),
                    ],
                    muted,
                )]
            }
            RibbonTab::Application => vec![
                group(
                    "Appearance",
                    vec![
                        gpui_kit::component::switch::Switch::new("dark-mode")
                            .label("Dark mode")
                            .checked(cx.theme().is_dark())
                            .on_click(|dark, window, cx| set_dark_mode(*dark, window, cx))
                            .into_any_element(),
                    ],
                    muted,
                ),
                group(
                    "Preferences",
                    vec![
                        command("settings", IconName::Settings, "Settings")
                            .tooltip_with_action(
                                "Edit the system prompt each chat tab sends",
                                &OpenSettings,
